INSERT INTO stt_utterance (utterance_id, call_id, seq, speaker, offset_sec, text, added_by, created_at) VALUES
(1, pg_temp.cid('CALL-0001'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(2, pg_temp.cid('CALL-0001'), 2, 'CUSTOMER', 5, '앱에서 타행으로 이체를 했는데 이십 분째 처리중으로만 나오고 완료가 안 돼요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(3, pg_temp.cid('CALL-0001'), 3, 'AGENT', 14, '불편을 드려 죄송합니다. 이체하신 금액과 시간 확인 부탁드립니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(4, pg_temp.cid('CALL-0001'), 4, 'CUSTOMER', 20, '오후 두 시쯤 삼백만 원 보냈어요. 돈은 빠져나갔는데 상대방은 못 받았대요. 갤럭시 S24 안드로이드 앱이에요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(5, pg_temp.cid('CALL-0001'), 5, 'AGENT', 34, '출금 후 미입금 건으로 확인됩니다. 전산 부서에 긴급으로 전달하겠습니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(6, pg_temp.cid('CALL-0006'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(7, pg_temp.cid('CALL-0006'), 2, 'CUSTOMER', 4, '인터넷뱅킹에서 공동인증서로 인증하려는데 인증서 오류가 나면서 진행이 안 돼요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(8, pg_temp.cid('CALL-0006'), 3, 'AGENT', 14, '오류 코드가 표시되나요?', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(9, pg_temp.cid('CALL-0006'), 4, 'CUSTOMER', 18, '인증 모듈 오류 코드 E-1203 이라고 나와요. 윈도우 11 PC고 엣지 브라우저예요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(10, pg_temp.cid('CALL-0006'), 5, 'AGENT', 30, '다른 PC에서도 같은 증상인지 확인 가능하실까요?', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(11, pg_temp.cid('CALL-0006'), 6, 'CUSTOMER', 35, '회사 직원들 PC에서도 전부 안 된다고 해요. 급여 이체를 해야 하는데 아무것도 안 돼요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(12, pg_temp.cid('CALL-0006'), 7, 'AGENT', 46, '다수 고객 영향으로 보여 인증 오류로 접수하고 전산 부서에 바로 전달하겠습니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(13, pg_temp.cid('CALL-0011'), 1, 'AGENT', 0, '안녕하세요 고객센터 이수진입니다 무엇을 도와드릴까요', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(14, pg_temp.cid('CALL-0011'), 2, 'CUSTOMER', 12, '아 네 저 지금 이체를 해야 되는데요 앱에서 계속 오류가 나요', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(15, pg_temp.cid('CALL-0011'), 3, 'AGENT', 24, '네 고객님 확인을 위해 성함과 생년월일 말씀 부탁드립니다', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(16, pg_temp.cid('CALL-0011'), 4, 'CUSTOMER', 36, '한도윤이고요 구십 년 삼월 이일이요', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(17, pg_temp.cid('CALL-0011'), 5, 'AGENT', 48, '네 확인 감사합니다 어느 단계에서 어떤 문구가 나오나요', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(18, pg_temp.cid('CALL-0011'), 6, 'CUSTOMER', 60, '어 그게 계좌이체 화면이고 마지막 확인을 누르면 일시적으로 서비스를 이용할 수 없습니다 라고 나와요 앱을 다시 켜도 똑같아요', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(19, pg_temp.cid('CALL-0011'), 7, 'AGENT', 72, '핸드폰 기종이 어떻게 되시나요?', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(20, pg_temp.cid('CALL-0011'), 8, 'CUSTOMER', 84, '아이폰 프로 17이에요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(21, pg_temp.cid('CALL-0011'), 9, 'AGENT', 96, '언제까지 보내셔야 하는 거래인가요 인터넷뱅킹이나 다른 계좌로 대신 보내실 수 있을까요', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(22, pg_temp.cid('CALL-0011'), 10, 'CUSTOMER', 108, '오늘 세 시까지 계약금을 보내야 하는데 십 분 남았어요 늦으면 계약이 취소될 수 있어요 인터넷뱅킹도 같은 오류고 지금 쓸 수 있는 다른 계좌도 없어요', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(23, pg_temp.cid('CALL-0011'), 11, 'AGENT', 120, '이체가 계속 막히고 지급 기한이 임박한 상황을 긴급 건으로 전달하겠습니다 확인된 처리 상황을 안내드리겠습니다', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(24, pg_temp.cid('CALL-0011'), 12, 'CUSTOMER', 132, '네 빨리 좀 부탁드려요', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(25, pg_temp.cid('DEMO-P1-2-PRE1'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(26, pg_temp.cid('DEMO-P1-2-PRE1'), 2, 'CUSTOMER', 12, '모바일 앱 로그인이 안 돼요. 로그인 누르면 서비스 이용이 안 된다고 나와요. 앱을 다시 켜도 똑같아요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(27, pg_temp.cid('DEMO-P1-2-PRE1'), 3, 'AGENT', 24, '언제부터 그러셨나요?', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(28, pg_temp.cid('DEMO-P1-2-PRE1'), 4, 'CUSTOMER', 36, '십 분 전쯤부터요. 계좌 화면까지 못 들어가요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(29, pg_temp.cid('DEMO-P1-2-PRE1'), 5, 'AGENT', 48, '확인해서 전달하겠습니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(30, pg_temp.cid('DEMO-P1-2-PRE2'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(31, pg_temp.cid('DEMO-P1-2-PRE2'), 2, 'CUSTOMER', 12, '모바일 앱 로그인이 안 돼요. 로그인 누르면 바로 서비스 이용이 안 된다고 나와요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(32, pg_temp.cid('DEMO-P1-2-PRE2'), 3, 'AGENT', 24, '앱을 종료하고 다시 실행해 보셨나요?', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(33, pg_temp.cid('DEMO-P1-2-PRE2'), 4, 'CUSTOMER', 36, '네. 다시 켜도 똑같고 계좌 화면까지 못 들어가요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(34, pg_temp.cid('DEMO-P1-2-PRE2'), 5, 'AGENT', 48, '확인해서 전달하겠습니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(35, pg_temp.cid('DEMO-P1-3-PRE1'), 1, 'AGENT', 0, '안녕하세요, 고객센터 박지훈입니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(36, pg_temp.cid('DEMO-P1-3-PRE1'), 2, 'CUSTOMER', 12, '모바일 앱에서 다른 은행으로 이체하는데 마지막 단계에서 ''거래 처리 중 오류가 발생했습니다''라고 나와요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(37, pg_temp.cid('DEMO-P1-3-PRE1'), 3, 'AGENT', 24, '거래내역에 이체 완료된 건이 있는지 확인해 주시겠어요?', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(38, pg_temp.cid('DEMO-P1-3-PRE1'), 4, 'CUSTOMER', 36, '완료된 이체는 없어요. 다시 해도 똑같은 오류예요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(39, pg_temp.cid('DEMO-P1-3-PRE1'), 5, 'AGENT', 48, '확인해서 전달하겠습니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(40, pg_temp.cid('DEMO-P1-3-PRE2'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(41, pg_temp.cid('DEMO-P1-3-PRE2'), 2, 'CUSTOMER', 12, '앱에서 다른 은행으로 이체하려는데 마지막에 거래 처리 중 오류가 발생했습니다라고 나오고 계속 실패해요.', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
(42, pg_temp.cid('DEMO-P1-3-PRE2'), 3, 'AGENT', 24, '이체 완료 여부를 먼저 확인해 주시겠어요?', NULL, pg_temp.ts('2026-11-01 18:52:00+09:00'::timestamptz)),
