(226, pg_temp.cid('CALL-1019-13'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-19 13:46:57+09:00'::timestamptz)),
(227, pg_temp.cid('CALL-1019-13'), 2, 'CUSTOMER', 5, '이사를 해서 주소를 바꾸고 싶어요.', NULL, pg_temp.ts('2026-10-19 13:47:02+09:00'::timestamptz)),
