(236, pg_temp.cid('CALL-1019-15'), 3, 'AGENT', 10, '앱 이체 메뉴의 자동이체 등록에서 출금 계좌와 납부일을 지정하시면 됩니다.', NULL, pg_temp.ts('2026-10-19 14:05:55+09:00'::timestamptz)),
(237, pg_temp.cid('CALL-1019-15'), 4, 'CUSTOMER', 17, '감사합니다.', NULL, pg_temp.ts('2026-10-19 14:06:02+09:00'::timestamptz)),
