(790, pg_temp.cid('CALL-1026-01'), 4, 'CUSTOMER', 14, '네 확인했어요. 세 번 다시 요청했는데 계속 안 와요.', NULL, pg_temp.ts('2026-10-26 09:02:57+09:00'::timestamptz)),
(791, pg_temp.cid('CALL-1026-01'), 5, 'AGENT', 19, '문자 발송 상태를 확인하도록 전산 부서에 접수하겠습니다.', NULL, pg_temp.ts('2026-10-26 09:03:02+09:00'::timestamptz)),
(792, pg_temp.cid('CALL-1026-02'), 1, 'AGENT', 0, '안녕하세요, 고객센터 박지훈입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 09:06:44+09:00'::timestamptz)),
(793, pg_temp.cid('CALL-1026-02'), 2, 'CUSTOMER', 5, '관리비 자동이체를 등록하려는데 마지막에 오류가 나서 등록이 안 돼요.', NULL, pg_temp.ts('2026-10-26 09:06:49+09:00'::timestamptz)),
(794, pg_temp.cid('CALL-1026-02'), 3, 'AGENT', 11, '어떤 문구가 나오는지 알려주시겠어요?', NULL, pg_temp.ts('2026-10-26 09:06:55+09:00'::timestamptz)),
(795, pg_temp.cid('CALL-1026-02'), 4, 'CUSTOMER', 15, '처리할 수 없는 요청입니다 라고 나와요. 두 번 했는데 똑같아요. 갤럭시 A54이에요.', NULL, pg_temp.ts('2026-10-26 09:06:59+09:00'::timestamptz)),
(796, pg_temp.cid('CALL-1026-02'), 5, 'AGENT', 23, '등록이 계속 안 되는 건으로 접수해 전산 부서에 확인 요청하겠습니다.', NULL, pg_temp.ts('2026-10-26 09:07:07+09:00'::timestamptz)),
(797, pg_temp.cid('CALL-1026-03'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 09:26:57+09:00'::timestamptz)),
(798, pg_temp.cid('CALL-1026-03'), 2, 'CUSTOMER', 5, '앱에서 계좌를 새로 만들고 있는데 신분증을 찍으면 다시 찍으라는 화면만 계속 나와요.', NULL, pg_temp.ts('2026-10-26 09:27:02+09:00'::timestamptz)),
(799, pg_temp.cid('CALL-1026-03'), 3, 'AGENT', 13, '밝은 곳에서 신분증 전체가 보이게 다시 촬영해 보시겠어요?', NULL, pg_temp.ts('2026-10-26 09:27:10+09:00'::timestamptz)),
(800, pg_temp.cid('CALL-1026-03'), 4, 'CUSTOMER', 18, '벌써 다섯 번 넘게 했는데 계속 그래요. 갤럭시 S24이에요.', NULL, pg_temp.ts('2026-10-26 09:27:15+09:00'::timestamptz));
INSERT INTO stt_utterance (utterance_id, call_id, seq, speaker, offset_sec, text, added_by, created_at) VALUES
(801, pg_temp.cid('CALL-1026-03'), 5, 'AGENT', 24, '재촬영 후에도 진행이 막혀 전산 확인이 필요해 보입니다. 접수해 드리겠습니다.', NULL, pg_temp.ts('2026-10-26 09:27:21+09:00'::timestamptz)),
(802, pg_temp.cid('CALL-1026-04'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 09:48:44+09:00'::timestamptz)),
(803, pg_temp.cid('CALL-1026-04'), 2, 'CUSTOMER', 5, '크롬으로 이체 화면 들어가면 버튼이 겹쳐서 잘 안 눌려요.', NULL, pg_temp.ts('2026-10-26 09:48:49+09:00'::timestamptz)),
(804, pg_temp.cid('CALL-1026-04'), 3, 'AGENT', 10, '엣지 브라우저로 이용해 보시겠어요?', NULL, pg_temp.ts('2026-10-26 09:48:54+09:00'::timestamptz)),
(805, pg_temp.cid('CALL-1026-04'), 4, 'CUSTOMER', 14, '엣지로 하니까 넘어갔어요.', NULL, pg_temp.ts('2026-10-26 09:48:58+09:00'::timestamptz)),
(806, pg_temp.cid('CALL-1026-04'), 5, 'AGENT', 18, '크롬 화면 오류는 전달하겠습니다.', NULL, pg_temp.ts('2026-10-26 09:49:02+09:00'::timestamptz)),
(807, pg_temp.cid('CALL-1026-05'), 1, 'AGENT', 0, '안녕하세요, 고객센터 박지훈입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 10:30:59+09:00'::timestamptz)),
(808, pg_temp.cid('CALL-1026-05'), 2, 'CUSTOMER', 5, '입금 알림이 한참 늦게 와요. 돈은 들어와 있는데 알림은 20분 뒤에 왔어요.', NULL, pg_temp.ts('2026-10-26 10:31:04+09:00'::timestamptz)),
(809, pg_temp.cid('CALL-1026-05'), 3, 'AGENT', 12, '입금은 정상 처리된 것으로 확인됩니다.', NULL, pg_temp.ts('2026-10-26 10:31:11+09:00'::timestamptz)),
(810, pg_temp.cid('CALL-1026-05'), 4, 'CUSTOMER', 16, '네 지금은 됐어요. 알림만 늦었어요.', NULL, pg_temp.ts('2026-10-26 10:31:15+09:00'::timestamptz)),
(811, pg_temp.cid('CALL-1026-05'), 5, 'AGENT', 20, '알림 지연은 전산 부서에 전달하겠습니다.', NULL, pg_temp.ts('2026-10-26 10:31:19+09:00'::timestamptz)),
(812, pg_temp.cid('CALL-1026-06'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 11:02:52+09:00'::timestamptz)),
(813, pg_temp.cid('CALL-1026-06'), 2, 'CUSTOMER', 5, 'ARS 인증하다가 전화가 갑자기 끊겼어요.', NULL, pg_temp.ts('2026-10-26 11:02:57+09:00'::timestamptz)),
(814, pg_temp.cid('CALL-1026-06'), 3, 'AGENT', 9, '불편을 드려 죄송합니다. 다시 인증을 시도해 보시겠어요?', NULL, pg_temp.ts('2026-10-26 11:03:01+09:00'::timestamptz)),
(815, pg_temp.cid('CALL-1026-06'), 4, 'CUSTOMER', 14, '아 다시 하니까 완료됐다고 나와요.', NULL, pg_temp.ts('2026-10-26 11:03:06+09:00'::timestamptz)),
(816, pg_temp.cid('CALL-1026-06'), 5, 'AGENT', 18, '완료되셨습니다. 끊김 현상은 확인하도록 전달하겠습니다.', NULL, pg_temp.ts('2026-10-26 11:03:10+09:00'::timestamptz)),
(817, pg_temp.cid('CALL-1026-07'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 11:08:19+09:00'::timestamptz)),
(818, pg_temp.cid('CALL-1026-07'), 2, 'CUSTOMER', 5, '휴대폰을 다크모드로 쓰는데 앱 안내 문구가 잘 안 보여요.', NULL, pg_temp.ts('2026-10-26 11:08:24+09:00'::timestamptz)),
(819, pg_temp.cid('CALL-1026-07'), 3, 'AGENT', 10, '화면 설정에서 라이트 모드로 바꾸면 잘 보이실 거예요. 개선 요청으로 전달하겠습니다.', NULL, pg_temp.ts('2026-10-26 11:08:29+09:00'::timestamptz)),
(820, pg_temp.cid('CALL-1026-07'), 4, 'CUSTOMER', 18, '네 라이트 모드로 바꾸니까 보여요.', NULL, pg_temp.ts('2026-10-26 11:08:37+09:00'::timestamptz)),
(821, pg_temp.cid('CALL-1026-08'), 1, 'AGENT', 0, '안녕하세요, 고객센터 박지훈입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 11:15:00+09:00'::timestamptz)),
(822, pg_temp.cid('CALL-1026-08'), 2, 'CUSTOMER', 5, '인터넷뱅킹에서 공동인증서로 로그인하려는데 인증 모듈 오류가 나요.', NULL, pg_temp.ts('2026-10-26 11:15:05+09:00'::timestamptz)),
(823, pg_temp.cid('CALL-1026-08'), 3, 'AGENT', 11, '화면에 오류 코드가 표시되나요?', NULL, pg_temp.ts('2026-10-26 11:15:11+09:00'::timestamptz)),
(824, pg_temp.cid('CALL-1026-08'), 4, 'CUSTOMER', 15, 'E-1207 라고 나와요. 윈도우 11 엣지 브라우저예요. 다시 해도 똑같아요.', NULL, pg_temp.ts('2026-10-26 11:15:15+09:00'::timestamptz)),
(825, pg_temp.cid('CALL-1026-08'), 5, 'AGENT', 22, '같은 오류 코드로 여러 문의가 들어오고 있어 전산 부서에 바로 전달하겠습니다.', NULL, pg_temp.ts('2026-10-26 11:15:22+09:00'::timestamptz)),
(826, pg_temp.cid('CALL-1026-09'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 11:26:00+09:00'::timestamptz)),
(827, pg_temp.cid('CALL-1026-09'), 2, 'CUSTOMER', 5, '인터넷뱅킹에서 공동인증서로 로그인하려는데 인증 모듈 오류가 나요.', NULL, pg_temp.ts('2026-10-26 11:26:05+09:00'::timestamptz)),
(828, pg_temp.cid('CALL-1026-09'), 3, 'AGENT', 11, '화면에 오류 코드가 표시되나요?', NULL, pg_temp.ts('2026-10-26 11:26:11+09:00'::timestamptz)),
(829, pg_temp.cid('CALL-1026-09'), 4, 'CUSTOMER', 15, 'E-1207 라고 나와요. 윈도우 10 크롬 브라우저예요. 다시 해도 똑같아요.', NULL, pg_temp.ts('2026-10-26 11:26:15+09:00'::timestamptz)),
(830, pg_temp.cid('CALL-1026-09'), 5, 'CUSTOMER', 22, '사무실 다른 PC들도 전부 같은 오류가 난다고 해요.', NULL, pg_temp.ts('2026-10-26 11:26:22+09:00'::timestamptz)),
(831, pg_temp.cid('CALL-1026-09'), 6, 'AGENT', 27, '같은 오류 코드로 여러 문의가 들어오고 있어 전산 부서에 바로 전달하겠습니다.', NULL, pg_temp.ts('2026-10-26 11:26:27+09:00'::timestamptz)),
(832, pg_temp.cid('CALL-1026-10'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 11:41:05+09:00'::timestamptz)),
(833, pg_temp.cid('CALL-1026-10'), 2, 'CUSTOMER', 5, '이체가 안 돼요. 한도를 초과했다고 나오는데 전 그렇게 많이 안 보냈거든요.', NULL, pg_temp.ts('2026-10-26 11:41:10+09:00'::timestamptz)),
(834, pg_temp.cid('CALL-1026-10'), 3, 'AGENT', 12, '확인해 보니 1일 이체한도가 100만 원으로 설정되어 있습니다. 오늘 이미 보내신 금액이 있어 초과됐습니다.', NULL, pg_temp.ts('2026-10-26 11:41:17+09:00'::timestamptz)),
(835, pg_temp.cid('CALL-1026-10'), 4, 'CUSTOMER', 22, '아 한도가 그렇게 낮았군요. 한도를 올리고 싶어요.', NULL, pg_temp.ts('2026-10-26 11:41:27+09:00'::timestamptz)),
(836, pg_temp.cid('CALL-1026-11'), 1, 'AGENT', 0, '안녕하세요, 고객센터 박지훈입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 11:45:51+09:00'::timestamptz)),
(837, pg_temp.cid('CALL-1026-11'), 2, 'CUSTOMER', 5, '대출 이자 납입일을 바꿀 수 있나요?', NULL, pg_temp.ts('2026-10-26 11:45:56+09:00'::timestamptz)),
(838, pg_temp.cid('CALL-1026-11'), 3, 'AGENT', 9, '연 1회 변경 가능하며 앱 대출관리 메뉴에서 신청하실 수 있습니다.', NULL, pg_temp.ts('2026-10-26 11:46:00+09:00'::timestamptz)),
(839, pg_temp.cid('CALL-1026-11'), 4, 'CUSTOMER', 15, '앱에서 해 볼게요.', NULL, pg_temp.ts('2026-10-26 11:46:06+09:00'::timestamptz)),
(840, pg_temp.cid('CALL-1026-12'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 11:51:00+09:00'::timestamptz)),
