(846, pg_temp.cid('CALL-1026-13'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 12:22:54+09:00'::timestamptz)),
(847, pg_temp.cid('CALL-1026-13'), 2, 'CUSTOMER', 5, '이사를 해서 주소를 바꾸고 싶어요.', NULL, pg_temp.ts('2026-10-26 12:22:59+09:00'::timestamptz)),
