(854, pg_temp.cid('CALL-1026-15'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 13:36:38+09:00'::timestamptz)),
(855, pg_temp.cid('CALL-1026-15'), 2, 'CUSTOMER', 5, '통장을 잃어버렸는데 재발행 되나요?', NULL, pg_temp.ts('2026-10-26 13:36:43+09:00'::timestamptz)),
(856, pg_temp.cid('CALL-1026-15'), 3, 'AGENT', 9, '신분증을 지참하고 영업점에 방문하시면 재발행 가능합니다.', NULL, pg_temp.ts('2026-10-26 13:36:47+09:00'::timestamptz)),
(857, pg_temp.cid('CALL-1026-15'), 4, 'CUSTOMER', 14, '네 방문할게요.', NULL, pg_temp.ts('2026-10-26 13:36:52+09:00'::timestamptz)),
(858, pg_temp.cid('CALL-1026-16'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 14:10:10+09:00'::timestamptz)),
