(860, pg_temp.cid('CALL-1026-16'), 3, 'AGENT', 9, '평일 오전 9시부터 오후 4시까지 운영하고 주말은 쉽니다.', NULL, pg_temp.ts('2026-10-26 14:10:19+09:00'::timestamptz)),
(861, pg_temp.cid('CALL-1026-16'), 4, 'CUSTOMER', 14, '평일에 갈게요.', NULL, pg_temp.ts('2026-10-26 14:10:24+09:00'::timestamptz)),
(862, pg_temp.cid('CALL-1026-17'), 1, 'AGENT', 0, '안녕하세요, 고객센터 박지훈입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-26 14:17:01+09:00'::timestamptz)),
