(959, pg_temp.cid('CALL-1027-19'), 4, 'CUSTOMER', 17, '네 감사합니다.', NULL, pg_temp.ts('2026-10-27 16:40:45+09:00'::timestamptz)),
(960, pg_temp.cid('CALL-1027-20'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-27 17:30:13+09:00'::timestamptz)),
