(963, pg_temp.cid('CALL-1027-20'), 4, 'CUSTOMER', 15, '앱에서 해 볼게요.', NULL, pg_temp.ts('2026-10-27 17:30:28+09:00'::timestamptz)),
(964, pg_temp.cid('CALL-1028-01'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-28 09:00:02+09:00'::timestamptz)),
(965, pg_temp.cid('CALL-1028-01'), 2, 'CUSTOMER', 5, '앱에서 계좌를 새로 만들고 있는데 신분증을 찍으면 다시 찍으라는 화면만 계속 나와요.', NULL, pg_temp.ts('2026-10-28 09:00:07+09:00'::timestamptz)),
(966, pg_temp.cid('CALL-1028-01'), 3, 'AGENT', 13, '밝은 곳에서 신분증 전체가 보이게 다시 촬영해 보시겠어요?', NULL, pg_temp.ts('2026-10-28 09:00:15+09:00'::timestamptz)),
(967, pg_temp.cid('CALL-1028-01'), 4, 'CUSTOMER', 18, '벌써 다섯 번 넘게 했는데 계속 그래요. 아이폰 14이에요.', NULL, pg_temp.ts('2026-10-28 09:00:20+09:00'::timestamptz)),
(968, pg_temp.cid('CALL-1028-01'), 5, 'AGENT', 24, '재촬영 후에도 진행이 막혀 전산 확인이 필요해 보입니다. 접수해 드리겠습니다.', NULL, pg_temp.ts('2026-10-28 09:00:26+09:00'::timestamptz)),
(969, pg_temp.cid('CALL-1028-02'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-28 09:46:15+09:00'::timestamptz)),
(970, pg_temp.cid('CALL-1028-02'), 2, 'CUSTOMER', 5, 'ARS에서 본인확인 하는데 인증번호 문자가 안 와요.', NULL, pg_temp.ts('2026-10-28 09:46:20+09:00'::timestamptz)),
(971, pg_temp.cid('CALL-1028-02'), 3, 'AGENT', 10, '스팸 문자함도 확인해 보셨을까요?', NULL, pg_temp.ts('2026-10-28 09:46:25+09:00'::timestamptz)),
(972, pg_temp.cid('CALL-1028-02'), 4, 'CUSTOMER', 14, '네 확인했어요. 세 번 다시 요청했는데 계속 안 와요.', NULL, pg_temp.ts('2026-10-28 09:46:29+09:00'::timestamptz)),
(973, pg_temp.cid('CALL-1028-02'), 5, 'AGENT', 19, '문자 발송 상태를 확인하도록 전산 부서에 접수하겠습니다.', NULL, pg_temp.ts('2026-10-28 09:46:34+09:00'::timestamptz)),
(974, pg_temp.cid('CALL-1028-03'), 1, 'AGENT', 0, '안녕하세요, 고객센터 박지훈입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-28 10:07:56+09:00'::timestamptz)),
(975, pg_temp.cid('CALL-1028-03'), 2, 'CUSTOMER', 5, '거래내역을 3개월로 조회하면 오류가 나요. 증빙 자료로 내야 하거든요.', NULL, pg_temp.ts('2026-10-28 10:08:01+09:00'::timestamptz)),
(976, pg_temp.cid('CALL-1028-03'), 3, 'AGENT', 11, '기간을 1개월로 줄여서 조회해 보시겠어요?', NULL, pg_temp.ts('2026-10-28 10:08:07+09:00'::timestamptz)),
(977, pg_temp.cid('CALL-1028-03'), 4, 'CUSTOMER', 15, '1개월도 똑같아요. 다시 해도 안 돼요. 아이폰 13 미니이에요.', NULL, pg_temp.ts('2026-10-28 10:08:11+09:00'::timestamptz)),
(978, pg_temp.cid('CALL-1028-03'), 5, 'AGENT', 21, '조회가 계속 실패해 전산 부서에 확인 요청하고, 급하시면 영업점 발급도 안내드리겠습니다.', NULL, pg_temp.ts('2026-10-28 10:08:17+09:00'::timestamptz)),
(979, pg_temp.cid('CALL-1028-04'), 1, 'AGENT', 0, '안녕하세요, 고객센터 정하나입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-28 10:30:12+09:00'::timestamptz)),
(980, pg_temp.cid('CALL-1028-04'), 2, 'CUSTOMER', 5, '입금 알림이 한참 늦게 와요. 돈은 들어와 있는데 알림은 20분 뒤에 왔어요.', NULL, pg_temp.ts('2026-10-28 10:30:17+09:00'::timestamptz)),
(981, pg_temp.cid('CALL-1028-04'), 3, 'AGENT', 12, '입금은 정상 처리된 것으로 확인됩니다.', NULL, pg_temp.ts('2026-10-28 10:30:24+09:00'::timestamptz)),
(982, pg_temp.cid('CALL-1028-04'), 4, 'CUSTOMER', 16, '네 지금은 됐어요. 알림만 늦었어요.', NULL, pg_temp.ts('2026-10-28 10:30:28+09:00'::timestamptz)),
(983, pg_temp.cid('CALL-1028-04'), 5, 'AGENT', 20, '알림 지연은 전산 부서에 전달하겠습니다.', NULL, pg_temp.ts('2026-10-28 10:30:32+09:00'::timestamptz)),
(984, pg_temp.cid('CALL-1028-05'), 1, 'AGENT', 0, '안녕하세요, 고객센터 이수진입니다. 무엇을 도와드릴까요?', NULL, pg_temp.ts('2026-10-28 10:47:00+09:00'::timestamptz)),
(985, pg_temp.cid('CALL-1028-05'), 2, 'CUSTOMER', 5, '거래내역 보는 데 너무 오래 걸려요. 30초는 기다린 것 같아요.', NULL, pg_temp.ts('2026-10-28 10:47:05+09:00'::timestamptz)),
(986, pg_temp.cid('CALL-1028-05'), 3, 'AGENT', 11, '지금은 조회가 되셨나요?', NULL, pg_temp.ts('2026-10-28 10:47:11+09:00'::timestamptz)),
